ion":"architectural_joiner"},{"code":"K32","kind":"knowledge","title":"Architectural joiner: Setting out and marking out techniques for joinery product manufacture and potential effects of marking out errors.","option":"architectural_joiner"},{"code":"K33","kind":"knowledge","title":"Architectural joiner: Timber joints, types and production techniques: Dovetails, mortise and tenon, bridals and halvings.","option":"architectural_joiner"},{"code":"K34","kind":"knowledge","title":"Architectural joiner: Manufacture and assembly techniques for standard right angled timber windows.","option":"architectural_joiner"},{"code":"K35","kind":"knowledge","title":"Architectural joiner: Connection methods in joinery: Dowels, biscuit, staples and adhesives.","option":"architectural_joiner"},{"code":"K36","kind":"knowledge","title":"Architectural joiner: Manufacture and assembly techniques for timber first fix products: 1. straight staircases 2. door frames and linings.","option":"architectural_joiner"},{"code":"K37","kind":"knowledge","title":"Architectural joiner: Manufacture and assembly techniques for second fix timber products: 1. timber wall and floor units 2. timber doors 3. timber mouldings.","option":"architectural_joiner"},{"code":"K38","kind":"knowledge","title":"Architectural joiner: Finishing techniques for manufactured timber products: Sanding, painting, waxing, polishing, oiling and applying preservative.","option":"architectural_joiner"},{"code":"K39","kind":"knowledge","title":"Architectural joiner: Ironmongery installation techniques.","option":"architectural_joiner"},{"code":"K40","kind":"knowledge","title":"Employment types (self employed and employed), small business start up principles and tax."},{"code":"S1","kind":"skill","title":"Comply with health and safety regulations, standards, and guidance."},{"code":"S2","kind":"skill","title":"Identify and use safety control equipment, for example, RPE, dust suppression, PPE and LEV."},{"code":"S3","kind":"skill","title":"Comply with environmental and sustainability regulations, standards, and guidance. Segregate resources for reuse, recycling and disposal."},{"code":"S4","kind":"skill","title":"Comply with industry regulations, standards, and guidance."},{"code":"S5","kind":"skill","title":"Prepare and maintain a safe working area."},{"code":"S6","kind":"skill","title":"Interpret and use information from drawings and specifications."},{"code":"S7","kind":"skill","title":"Estimate required materials and produce a cutting list."},{"code":"S8","kind":"skill","title":"Verbally communicate with others, applying construction terminology."},{"code":"S9","kind":"skill","title":"Select, use and store hand tools."},{"code":"S10","kind":"skill","title":"Select, use and store power tools."},{"code":"S11","kind":"skill","title":"Maintain and sharpen hand tools."},{"code":"S12","kind":"skill","title":"Produce jigs."},{"code":"S13","kind":"skill","title":"Identifies well-being support available to self and others."},{"code":"S14","kind":"skill","title":"Site carpenter: Apply first fix techniques and practices for: 1. structural carcassing (load bearing studwork), 2. straight timber or metal partition walls, 3. floor joists 4. floor joist coverings and 5. straight flights of stairs.","option":"site_carpenter"},{"code":"S15","kind":"skill","title":"Site carpenter: Install structural fixings.","option":"site_carpenter"},{"code":"S16","kind":"skill","title":"Site carpenter: Size timber from sizing tables.","option":"site_carpenter"},{"code":"S17","kind":"skill","title":"Site carpenter: Apply site second fix techniques and practices for: 1. service encasement, 2. cladding 3. wall and floor units and fitments, 4. handrails and spindles to straight flights of stairs, 5. internal and external doors, 6. skirting boards and architrave, 7. window boards.","option":"site_carpenter"},{"code":"S18","kind":"skill","title":"Site carpenter: Apply site carpenter techniques and practices to construction of rafter roofs, including trussed (prefabricated) and traditional (built on site) including the construction of verge, eaves and fitting loft access.","option":"site_carpenter"},{"code":"S19","kind":"skill","title":"Site carpenter: Use and store laser levels for example cross line laser.","option":"site_carpenter"},{"code":"S20","kind":"skill","title":"Site carpenter: Form connections, for example, using joints, nails, screws, bolts and adhesive.","option":"site_carpenter"},{"code":"S21","kind":"skill","title":"Site carpenter: Apply measuring, marking out, cutting (square and angled), mitring, hinging and recessing techniques.","option":"site_carpenter"},{"code":"S22","kind":"skill","title":"Site carpenter: Carrying out splicing and scribing techniques.","option":"site_carpenter"},{"code":"S23","kind":"skill","title":"Architectural joiner: Produce setting out details, including setting rods, and mark out for timber products.","option":"architectural_joiner"},{"code":"S24","kind":"skill","title":"Architectural joiner: Produce basic woodworking joints including dovetail, bridal, mortise and tenon and halving.","option":"architectural_joiner"},{"code":"S25","kind":"skill","title":"Architectural joiner: Form connections using dowels, biscuit, staples and adhesives.","option":"architectural_joiner"},{"code":"S26","kind":"skill","title":"Architectural joiner: Apply techniques and practices to the manufacture and assembly of a timber window with casement including glazing rebates and associated ironmongery.","option":"architectural_joiner"},{"code":"S27","kind":"skill","title":"Architectural joiner: Apply manufacture and assembly techniques for first fix products: 1. straight staircases, 2. door frames and linings.","option":"architectural_joiner"},{"code":"S28","kind":"skill","title":"Architectural joiner: Apply manufacture and assembly techniques for second fix products: 1. timber doors, 2. wall and floor units, 3. timber mouldings, 4. staircase spindles and balustrades.","option":"architectural_joiner"},{"code":"S29","kind":"skill","title":"Architectural joiner: Fit ironmongery including door locks, door handles, door hinges, latches and draw runners.","option":"architectural_joiner"},{"code":"S30","kind":"skill","title":"Architectural joiner: Inspect, prepare and operate fixed machinery.","option":"architectural_joiner"},{"code":"B1","kind":"behaviour","title":"Put health, safety and wellbeing first."},{"code":"B2","kind":"behaviour","title":"Consider the environment when using resources and carrying out processes."},{"code":"B3","kind":"behaviour","title":"Contribute to an inclusive and diverse culture."},{"code":"B4","kind":"behaviour","title":"Seek learning and development opportunities."},{"code":"B5","kind":"behaviour","title":"Team-focus to meet team goals including, considering the wider build team."}]}$std$::jsonb, null);
